# Apply authentication bypass fixes to ssh_connection.erl

FILE="/app/workspace/otp_src_27.3.2/lib/ssh/src/ssh_connection.erl"

# Create backup
cp "$FILE" "${FILE}.original"

# Fix 1: Add authentication check to session channel open handler
# Replace: server, _SSH) -> with server, SSH) -> and add case statement
sed -i '/handle_msg(#ssh_msg_channel_open{channel_type = "session"/,/end;/{
    s/server, _SSH) ->/server, SSH) ->\n    %% SECURITY: Check if user is authenticated\n    case SSH#ssh.authenticated of\n        true ->/
    s/end;$/end\n        ;\n        false ->\n            FailMsg = channel_open_failure_msg(RemoteId, ?SSH_OPEN_ADMINISTRATIVELY_PROHIBITED, "Unauthenticated", "en"),\n            {[{connection_reply, FailMsg}], Connection0}\n    end;/
}' "$FILE"

# Fix 2: Add authentication check to subsystem request handler
sed -i '/handle_msg(#ssh_msg_channel_request{recipient_channel = ChannelId,/{
    /request_type = "subsystem"/,/server, _SSH) ->/s/server, _SSH) ->/server, SSH) when SSH#ssh.authenticated =/
}' "$FILE"

# Fix 3: Add authentication check to shell request handler
sed -i '/handle_msg(#ssh_msg_channel_request{recipient_channel = ChannelId,/{
    /request_type = "shell"/,/server, _SSH) ->/s/server, _SSH) ->/server, SSH) when SSH#ssh.authenticated =/
}' "$FILE"

# Fix 4: Add authentication check to exec request handler
sed -i '/handle_msg(#ssh_msg_channel_request{recipient_channel = ChannelId,/{
    /request_type = "exec"/,/server, _SSH) ->/s/server, _SSH) ->/server, SSH) when SSH#ssh.authenticated =/
}' "$FILE"

# Fix 5: Add authentication check to pty-req handler
sed -i '/handle_msg(#ssh_msg_channel_request{recipient_channel = ChannelId,/{
    /request_type = "pty-req"/,/server, _SSH) ->/s/server, _SSH) ->/server, SSH) when SSH#ssh.authenticated =/
}' "$FILE"

# Fix 6: Add authentication check to env request handler
sed -i '/handle_msg(#ssh_msg_channel_request{recipient_channel = ChannelId,/{
    /request_type = "env"/,/server, _SSH) ->/s/server, _SSH) ->/server, SSH) when SSH#ssh.authenticated =/
}' "$FILE"

# Fix 7: Add authentication check to tcpip-forward global request handler
sed -i '/handle_msg(#ssh_msg_global_request{name = <<"tcpip-forward">>/,/server, _SSH) ->/s/server, _SSH) ->/server, SSH) when SSH#ssh.authenticated =/g' "$FILE"

echo "Patches applied to $FILE"

